CREATE TABLE "Meeting_types" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "type" text NOT NULL
);

CREATE TABLE "Tags" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" text NOT NULL UNIQUE
);

CREATE TABLE "Users" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" character varying(100) NOT NULL,
  "surname" character varying(100) NOT NULL,
  "role" text NOT NULL,
  "login" character varying(100) NOT NULL UNIQUE,
  "password_hash" text NOT NULL
);

CREATE TABLE "Companies" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" integer NOT NULL UNIQUE,
  "company_name" text NOT NULL,
  "contact_email" text
);

CREATE TABLE "Files" (
  "id" uuid PRIMARY KEY,
  "user_id" integer NOT NULL,
  "group_id" integer,
  "original_name" text NOT NULL,
  "gcs_bucket" text NOT NULL,
  "gcs_object_name" text NOT NULL,
  "content_type" text NOT NULL,
  "size_bytes" bigint NOT NULL,
  "created_at" timestamp with time zone NOT NULL
);

CREATE TABLE "Notifications" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" integer NOT NULL,
  "content" text NOT NULL,
  "status" text NOT NULL,
  "created_at" timestamp with time zone NOT NULL,
  "link_target" text,
  "group_request_id" integer
);

CREATE TABLE "Project" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" integer NOT NULL,
  "topic" text NOT NULL,
  "description" text,
  "project_goal" text,
  "work_scope" text,
  "needed_technologies" text,
  "created_at" timestamp with time zone NOT NULL,
  "max_groups" integer,
  "max_number_group_members" integer NOT NULL,
  "meeting_type_id" integer NOT NULL,
  "partnership_type" text,
  "language_doc" text NOT NULL,
  "notes" text,
  "priority" integer NOT NULL
);

CREATE TABLE "GroupRequests" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "group_id" integer NOT NULL,
  "project_id" integer,
  "student_id" integer,
  "created_by_user_id" integer NOT NULL,
  "status" text NOT NULL DEFAULT 'Pending',
  "type" text,
  "created_at" timestamp with time zone NOT NULL,
  "responded_at" timestamp with time zone
);

CREATE TABLE "Comments" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" integer NOT NULL,
  "project_id" integer NOT NULL,
  "content" text NOT NULL,
  "created_at" timestamp with time zone NOT NULL
);

CREATE TABLE "Responses" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "comment_id" integer NOT NULL,
  "user_id" integer NOT NULL,
  "content" text NOT NULL,
  "created_at" timestamp with time zone NOT NULL
);

CREATE TABLE "Groups" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" text NOT NULL,
  "project_id" integer,
  "is_accepted" text,
  "leader_id" integer,
  "max_members" integer
);

CREATE TABLE "Students" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" integer NOT NULL UNIQUE,
  "group_id" integer,
  "email" text NOT NULL
);

CREATE TABLE "GroupFiles" (
  "group_id" integer NOT NULL,
  "file_id" uuid NOT NULL,
  PRIMARY KEY ("group_id", "file_id")
);

CREATE TABLE "CalendarEvents" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "time" timestamp with time zone NOT NULL,
  "group_id" integer NOT NULL,
  "name" text NOT NULL
);

CREATE TABLE "ProjectTags" (
  "project_id" integer NOT NULL,
  "tag_id" integer NOT NULL,
  PRIMARY KEY ("project_id", "tag_id")
);

CREATE TABLE "ProjectFiles" (
  "id" uuid PRIMARY KEY,
  "original_file_name" character varying(255) NOT NULL,
  "gcs_object_name" character varying(512) NOT NULL,
  "content_type" character varying(255) NOT NULL,
  "team_id" integer NOT NULL,
  "upload_date" timestamp with time zone NOT NULL
);

