ALTER TABLE "Students"
  ADD CONSTRAINT "FK_Students_Users_user_id"
  FOREIGN KEY ("user_id") REFERENCES "Users" ("id") ON DELETE CASCADE;

ALTER TABLE "Students"
  ADD CONSTRAINT "FK_Students_Groups_group_id"
  FOREIGN KEY ("group_id") REFERENCES "Groups" ("id") ON DELETE SET NULL;

ALTER TABLE "GroupRequests"
  ADD CONSTRAINT "FK_GroupRequests_Groups_group_id"
  FOREIGN KEY ("group_id") REFERENCES "Groups" ("id") ON DELETE CASCADE;

ALTER TABLE "GroupRequests"
  ADD CONSTRAINT "FK_GroupRequests_Project_project_id"
  FOREIGN KEY ("project_id") REFERENCES "Project" ("id") ON DELETE SET NULL;

ALTER TABLE "GroupRequests"
  ADD CONSTRAINT "FK_GroupRequests_Students_student_id"
