ALTER TABLE "GroupFiles"
  ADD CONSTRAINT "FK_GroupFiles_Groups_group_id"
  FOREIGN KEY ("group_id") REFERENCES "Groups" ("id") ON DELETE CASCADE;

ALTER TABLE "GroupFiles"
  ADD CONSTRAINT "FK_GroupFiles_Files_file_id"
  FOREIGN KEY ("file_id") REFERENCES "Files" ("id") ON DELETE CASCADE;

ALTER TABLE "CalendarEvents"
  ADD CONSTRAINT "FK_CalendarEvents_Groups_group_id"
  FOREIGN KEY ("group_id") REFERENCES "Groups" ("id") ON DELETE CASCADE;

ALTER TABLE "ProjectTags"
  ADD CONSTRAINT "FK_ProjectTags_Project_project_id"
  FOREIGN KEY ("project_id") REFERENCES "Project" ("id") ON DELETE CASCADE;

ALTER TABLE "ProjectTags"
  ADD CONSTRAINT "FK_ProjectTags_Tags_tag_id"
  FOREIGN KEY ("tag_id") REFERENCES "Tags" ("id") ON DELETE CASCADE;

