-- Partial unique indexes to prevent duplicate pending requests
CREATE UNIQUE INDEX IF NOT EXISTS ux_group_invite_pending
  ON "GroupRequests"(group_id, student_id)
  WHERE type = 'Invitation' AND status = 'Pending';

CREATE UNIQUE INDEX IF NOT EXISTS ux_group_application_pending
  ON "GroupRequests"(group_id, student_id)
  WHERE type = 'Application' AND status = 'Pending';

CREATE UNIQUE INDEX IF NOT EXISTS ux_group_projectreq_pending
  ON "GroupRequests"(group_id, project_id)
  WHERE type = 'ProjectRequest' AND status = 'Pending' AND project_id IS NOT NULL;

